import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"巽","description":"东坡易传 - 巽","frontmatter":{"title":"巽","description":"东坡易传 - 巽"},"headers":[],"relativePath":"zh/classics/dongpo/058.md","filePath":"zh/classics/dongpo/058.md"}'),o={name:"zh/classics/dongpo/058.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><p>“巽”：小亨，利有攸往，利見大人。</p><p>《彖》曰：重巽以申命。剛“巽”乎中正而志行，柔皆順乎剛，是以“小亨，利有攸往，利見大人。”</p><p>君子和而不同，以“巽”繼“巽”，小人之道也。無施而可，故用於申命而已。所以爲“巽”者，初與四也。二五雖據用事之地，而權不在焉，故曰“剛‘巽’乎中正而志行”，言必用初與四而後得志也。權雖在初與四，而非用事之地，故曰：“柔皆順乎剛，是以小亨，”言必順二五而後亨也。“利有攸往”，爲二、五用也；“利見大人”，見九五也。有其權而無其位，非九五之大人，孰能容之？</p><p>象曰：隨風，“巽”，君子以申命行事。</p><p>“申”，重也；兩風相因，是謂“隨風”，申命之象也。古之爲令者，必反覆申明之，然後事必行。</p><p>初六：進退，利武人之貞。象曰：“進退”，志疑也；“利武人之貞”，志治也。</p><p>初六有其權而無其位，九二、九三之所病，故疑而進退也。小人而權在焉，則《易》謂之武人；武人負其力而不貞於君，志亂也；及其治也，則以貞於其君爲利。</p><p>九二：巽在牀下，用史、巫紛若，吉，無咎。象曰：“紛若”之“吉”，得中也。</p><p>九二以陽居陰，能下人者也。知權在初六，故“巽”於牀下，下之而求用也。初六，武人也；方且進退，我則下之而求其用，故求者紛然，而用者不力。譬之用史、巫，將以求福於神，神之降福未可知，而史、巫先享其利也。故“吉”而後“無咎”。紛然而求人者，非吉之道也，其所以吉者，居得其中，用事之地也。</p><p>九三：頻巽，吝。象曰：“頻巽”之“吝”，志窮也。</p><p>九三以陽居陽，而非用事之地也。知權之在初六也，下之則心不服，制之則力不能，故頻蹙以待之。“復”之六三不能止初九之爲“復”也，故“頻復”；“巽”之九三不能止初六之爲“巽”也，故“頻巽”。</p><p>六四：悔亡，田獲三品。象曰：“田獲三品”，有功也。</p><p>六四，有其權而無其位者，與初六均也，蓋亦居可疑之地矣。而有九五以爲之主，坦然以正待之，故“悔亡”。九五不求，而六四自求用，故其用也力。譬之於田：田者盡力以獲禽，而利歸於君。“一爲乾豆，二爲賓客，三爲充者之庖。”君子不勞而“獲三品”，其與史巫之功亦遠矣。</p><p>九五：貞吉，悔亡，無不利。無初有終。先庚三日，後庚三日，吉。象曰：九五之吉，位正中也。</p><p>九五履中正之位，進不頻蹙以忌四，退不過“巽”以下之，蓋貞而已矣。此四所以心服而爲之用也，是以“吉”且“悔亡”而“無不利”。“無不利”者，四與五皆利也。九五之德如此，故有“後庚”之終“吉”。</p><p>上九：巽在牀下，喪其資斧，貞兇。象曰：“巽在牀下”，上窮也；“喪其資斧”，正乎兇也。</p><p>九二以陽居陰，上九處“巽”之極，故皆“巽”於牀下。而上九陽亢於上，非能下人者也；九二之“巽”，將以用初六；而上九之“巽”，將以圖六四也，有用斧之意焉，特以處於無位之地，故喪其斧也。以上下言之則“正”，以勢言之則“兇”。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
